import{z as i,x as d,o as l,c as A,q as B,j as n,D as e,d as t,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"图表与表格理解","description":"","frontmatter":{"title":"图表与表格理解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/chart-table-understanding.md","filePath":"llm/chart-table-understanding.md","lastUpdated":1791063341000}'),p={name:"llm/chart-table-understanding.md"};function m(h,a,c,u,D,f){const r=d("Mermaid");return l(),A("div",null,[a[2]||(a[2]=B('<h1 id="图表与表格理解" tabindex="-1">图表与表格理解 <a class="header-anchor" href="#图表与表格理解" aria-label="Permalink to &quot;图表与表格理解&quot;">​</a></h1><div class="epigraph"><p>柱的高度是几何，不是名词。把图当成场景描述，数轴与图例会先死在流畅的错答里。</p><footer>—— Masry 等 ChartQA；Liu 等 DePlot；文档侧对照 [OCR 与文档 VLM](/llm/ocr-vlm)</footer></div><p><a href="/llm/gui-grounding">上一课</a>读的是控件。<a href="/llm/ocr-vlm">OCR</a> 读的是字。缺口是把几何量译成数：轴刻度、图例颜色、柱高、单元格行列。后课长视频默认单帧结构已经能读，再加时间维。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ChartQA 一类题要看图作答，答案常是数或短短语。失败模式不是「没看见图」，而是：轴范围读错、把装饰当数据、图例颜色绑错系列、表格跨页对错列。强制 squish 的 <a href="/llm/vit-as-encoder">ViT</a> 会把细刻度糊进同一 patch；<a href="/llm/clip">CLIP</a> 标题先验会把常见图表故事写出来，与这张图的真实柱高无关。</p><p><span class="marginnote">「语言先验」就是模型从训练语料里背下的「图表套路」：比如见标题带「失业率」就按惯例描述先升后降。危险在于答案说得同样流利——错不是结巴出来的，而是自信地编出来的，读者很难凭语气分辨。</span></p><p>DePlot 把图表先译成表（plot-to-table），再在表上推理，把视觉识别与算术拆开。端到端 VLM 则要求同一 <a href="/llm/llava-projector">投影器</a> 前缀同时支撑读刻度与计算。</p><p><span class="marginnote">为什么主张「先转表再算」：语言模型口算多位数乘除常翻车，而把读数和计算拆成两步后，读错了可以对着表逐格核对，算错了可以交给代码执行——每一步都能单独验证，混在一步里就只能对着最终答案猜是哪错了。</span></p><p><span class="marginnote">表可以是图（扫描件）或已解析的 HTML/Markdown。本课管「当图像看的表」。已解析表应走文本，不要浪费视觉 token。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分辨率与长宽比优先：宽表用横条切格（<a href="/llm/anyres">AnyRes</a> 或原生分辨率）。监督要含：转写为 Markdown/CSV、读指定单元格、读轴上的值，而不只是「这是什么图」。算术应允许先抽取数字再算，避免口算与读图绑死。评测：ChartQA 等与纯 OCR、纯表格 QA 分列；检查「数对了但系列绑错」。</p>',11)),(l(),n(s,null,{default:e(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%9B%BE%E8%A1%A8%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20GEO%5B%22%E8%BD%B4%20%2F%20%E5%9B%BE%E4%BE%8B%20%2F%20%E5%87%A0%E4%BD%95%22%5D%0A%20%20GEO%20--%3E%20TAB%5B%22%E8%A1%A8%E6%88%96%E6%95%B0%E5%88%97%22%5D%0A%20%20TAB%20--%3E%20QA%5B%22%E9%97%AE%E7%AD%94%E4%B8%8E%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"读图是把像素几何逆映射到数据坐标：柱顶相对原点的比例 × 轴量程。这依赖格子仍分辨刻度线，以及模型把图例颜色当作键去查系列。语言先验提供的是「失业率图通常长这样」，不能提供这张图的读数。",-1)),(l(),n(s,null,{default:e(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%9F%B1%E9%A1%B6%E5%83%8F%E7%B4%A0%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20R%5B%22%E7%9B%B8%E5%AF%B9%E8%BD%B4%E5%BA%95%E7%9A%84%E9%AB%98%E5%BA%A6%E6%AF%94%E4%BE%8B%22%5D%0A%20%20R%20--%3E%20V%5B%22%E6%AF%94%E4%BE%8B%20%C3%97%20%E8%BD%B4%E9%87%8F%E7%A8%8B%20%3D%20%E8%AF%BB%E6%95%B0%22%5D%0A%20%20LG%5B%22%E5%9B%BE%E4%BE%8B%E9%A2%9C%E8%89%B2%22%5D%20--%3E%20K%5B%22%E6%9F%A5%E5%88%B0%E6%89%80%E5%B1%9E%E7%B3%BB%E5%88%97%22%5D%0A%20%20K%20--%3E%20V%0A%20%20P%5B%22%E8%AF%AD%E8%A8%80%E5%85%88%E9%AA%8C%EF%BC%9A%E8%BF%99%E7%B1%BB%E5%9B%BE%E9%80%9A%E5%B8%B8%E9%95%BF%E4%BB%80%E4%B9%88%E6%A0%B7%22%5D%20-.%20%22%E7%BB%95%E8%BF%87%E5%87%A0%E4%BD%95%E7%9B%B4%E6%8E%A5%E7%BC%96%E6%95%B0%22%20.-%3E%20V%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">代入一个数：轴底（0）在像素 y=500，轴顶（100）在 y=100，柱顶画在 y=280。读数 =（500−280）/（500−100）× 100 = 55。模型要做的就是把这三样——两个轴锚点加柱顶位置——都看准，任何一处看错读数就错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>抽取对了仍可能算错；算对了也可能看错系列。下一课把画布换成视频：结构问题变成时间采样与记忆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图表理解是几何到数字，不是场景描述。</li><li>先读成表再推理，可把识别与算术解耦。</li><li>分辨率与长宽比决定刻度是否还在。</li><li>出处：ChartQA；DePlot。</li></ul>',5))])}const C=i(p,[["render",m]]);export{T as __pageData,C as default};
